@'
import fs from 'node:fs';
let c=fs.readFileSync('CONTRIBUTING.md','utf8');
for(const code of ['L02','L04','L06','L08']){c=c.split('\n').map(line=>line.includes('[DIP-'+code+']')?line.replace(/\|[^|]+\|\s*$/,'| Delivered in v0.3.8 |'):line).join('\n');}
c=c.replace('L01, L04, L08 and the semantic roadmap have partial progress; their remaining criteria stay open.','L02, L04, L06 and the bounded L08 profiling work were delivered in v0.3.8. L01 and the semantic roadmap retain unfinished criteria; semantic routing, universal agent compliance and platform-wide latency guarantees are not implied.');fs.writeFileSync('CONTRIBUTING.md',c);
const config=JSON.parse(fs.readFileSync('.dip/config.json'));Object.assign(config.verification,{
 'intent-transitions':{command:['node','--test','--test-name-pattern','follow-up|adoption|CLI kind','test/low-friction.test.js'],timeoutMs:60000},
 'portable-intent':{command:['node','--test','--test-name-pattern','portable|repository integration','test/low-friction.test.js'],timeoutMs:60000},
 'client-discovery':{command:['node','--test','--test-name-pattern','isomorphic-git','test/low-friction.test.js'],timeoutMs:60000},
 'scale-evidence':{command:['node','scripts/scale-evidence.mjs'],timeoutMs:60000}
});fs.writeFileSync('.dip/config.json',JSON.stringify(config,null,2)+'\n');
'@ | node --input-type=module
npx prettier --write src/portable.js src/health.js test/low-friction.test.js scripts/scale-evidence.mjs docs/benchmarks/scale.md docs/benchmarks/README.md README.md CONTRIBUTING.md .dip/config.json
node --disable-warning=ExperimentalWarning --test test/low-friction.test.js
